import sys
from itertools import product

def hamming_distance(s1, s2):
    return sum(c1 != c2 for c1, c2 in zip(s1, s2))

def backtrack(current_code, used, n, p, P):
    if len(current_code) == 2**n:
        return current_code

    last_string = current_code[-1]
    for candidate in product('01', repeat=n):
        candidate_str = ''.join(candidate)
        if candidate_str not in used and hamming_distance(last_string, candidate_str) in P:
            used.add(candidate_str)
            result = backtrack(current_code + [candidate_str], used, n, p, P)
            if result:
                return result
            used.remove(candidate_str)

    return None

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    p = int(data[1])
    P = set(map(int, data[2:2+p]))

    start_string = '0' * n
    used = {start_string}
    result = backtrack([start_string], used, n, p, P)

    if result:
        for code in result:
            print(code)
    else:
        print("impossible")

